 if(b.dataset.kmapCell!==undefined&&session&&session.feedback===null){sound('tap');const cell=Number(b.dataset.kmapCell),at=session.value.indexOf(cell);if(at>=0)session.value.splice(at,1);else session.value.push(cell);renderSession();return;}
 if(b.dataset.subject){switchSubject(b.dataset.subject);return;}
 const action=b.dataset.action;
 if(action==='jump-current'){const current=nextLesson(),unit=units.find(u=>current.lecture>=u.range[0]&&current.lecture<=u.range[1]);if(unit&&unit.id!==activeUnit){activeUnit=unit.id;render();}scrollToCurrentLesson(true);return;}if(action==='retry-subject'){switchSubject(loadingSubject.id);return;}if(action==='subjects'){location.hash='subjects';}else if(action==='theme'){progress.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';store.setItem('csquest-theme',progress.settings.theme);save();render();if(session)renderSession();}else if(action==='continue')continueLearning();else if(action==='practice')startPractice();else if(action==='units')unitsDialog();else if(action==='guide'){const u=units[activeUnit];openDialog(`<div class="modal-heading"><h2>${h(u.title)}</h2><button class="icon-button" data-action="close" aria-label="Close">${icon('close')}</button></div><p>${h(u.goal)}</p><h3>Your small steps</h3><ul class="guide-list">${lecturePlans.slice(u.range[0],u.range[1]+1).map(l=>`<li>${icon('check')} ${h(l[0])}</li>`).join('')}</ul><p class="muted">Learn → manipulate → apply. Wrong answers get an explanation and another try.</p>`,'unit-dialog');}
 else if(action==='resume-saved'){const draft=readDrafts()[0];if(draft)resumeDraft(draft);}else if(action==='discard-saved'){const draft=readDrafts()[0];if(draft){removeDraft(draft.id);render();toast('Paused answers cleared. Your completed progress is unchanged.');}}else if(action==='dismiss-welcome'){uiPrefs.onboarded=true;savePreferences();render();}else if(action==='motion'){uiPrefs.motion=uiPrefs.motion==='reduced'?'system':'reduced';savePreferences();render();}else if(action==='concept-hint'){if(!session.showHint)session.hints=(session.hints||0)+1;session.showHint=!session.showHint;renderSession();}else if(action==='next-lesson'){session=null;closeDialog();startLesson(nextLesson().id);}else if(action==='view-progress'){session=null;closeDialog();location.hash='progress';}else if(action==='hearts')toast('Five learning hearts per round. Even if they run out, you can keep practicing.');
