async function pollStatus(){if(!authenticated()||loadingSubject)return;const requestSubject=selectedSubject.id,requestEpoch=subjectEpoch;try{const res=await fetch('/api/status?subject='+selectedSubject.id,{signal:AbortSignal.timeout(5000)});if(res.status===401){lockAccount();return;}if(!res.ok)throw new Error('Status unavailable');const previous=status;const received=await res.json();if(requestSubject!==selectedSubject.id||requestEpoch!==subjectEpoch)return;status=received;const previouslyReady=lessons.filter(l=>l.ready).length;const previousVersions=lessons.map(l=>l.contentVersion||0).join(',');for(const source of status.lessonSources||[]){const l=lessons.find(l=>l.id===source.id);if(l)Object.assign(l,source,{ready:l.ready||source.ready===true});}if(!previous&&!session)activeUnit=nextUnit(lessons,progress,units);if(!session&&(lessons.filter(l=>l.ready).length!==previouslyReady||previousVersions!==lessons.map(l=>l.contentVersion||0).join(',')))render();if(route==='roadmap'&&!session)$('#main').innerHTML=roadmapView();if(previous&&(lessons.filter(l=>l.ready).length!==previouslyReady||lessons.map(l=>l.contentVersion||0).join(',')!==previousVersions))toast('New learning material is available.');}catch{if(requestSubject!==selectedSubject.id||requestEpoch!==subjectEpoch)return;status={...status,connectionError:true};}}
if(authenticated())await switchSubject(store.getItem('csquest-subject')||'coa',true);else render();setInterval(pollStatus,60000);
