function cacheExercise(q){const s=session,rows=traceCache(q),disabled=s.feedback!==null?'disabled':'';return `<div class="cache-config"><span>${q.sets} SETS</span><span>${q.ways} WAYS</span><span>${q.policy}</span><span>START: EMPTY</span></div><p class="exercise-hint">Pick HIT or MISS for each block. After checking, explore every cache state.</p><div class="cache-accesses">${q.accesses.map((block,i)=>`<div class="cache-access"><span>${i+1}</span><b>Block ${block}<small>Set ${block%q.sets}</small></b><button class="tile ${s.value[i]===true?'chosen':''}" data-cache-step="${i}" data-cache-hit="true" ${disabled}>HIT</button><button class="tile ${s.value[i]===false?'chosen':''}" data-cache-step="${i}" data-cache-hit="false" ${disabled}>MISS</button></div>`).join('')}</div>${s.feedback!==null?`<div class="cache-timeline">${rows.map((r,i)=>`<details><summary>Access ${i+1}: block ${r.block} · ${r.hit?'HIT':'MISS'}${r.evicted!==null?' · evict '+r.evicted:''}</summary><div class="cache-state">${r.state.map((set,j)=>`<span>Set ${j}: <b>${set.join(' · ')||'empty'}</b></span>`).join('')}</div></details>`).join('')}</div>`:''}`;}
function errorsView(){const entries=progress.mistakes.map(m=>{const [lid,qi]=m.key.split(':').map(Number),l=lessons.find(l=>l.id===lid);return l&&l.questions[qi]?{m,l,q:l.questions[qi]}:null;}).filter(Boolean).sort((a,b)=>(b.m.lastMissedAt||0)-(a.m.lastMissedAt||0)),due=entries.filter(e=>e.m.due<=Date.now()&&e.m.status!=='resolved').length;return `<div class="page-eyebrow">MISTAKES ARE PART OF THE ADVENTURE</div><h1>Your practice errors.</h1><p class="page-description">See what tripped you up, understand why, and try again. Two clean practice recalls mark a concept as mastered.</p><div class="error-stats"><div class="card"><strong>${entries.length}</strong><span>Saved mistakes</span></div><div class="card"><strong>${due}</strong><span>Ready to revisit</span></div><div class="card"><strong>${entries.filter(e=>e.m.status==='resolved').length}</strong><span>Mastered</span></div></div><div class="error-toolbar"><label>Show <select id="error-filter"><option value="all">All mistakes</option><option value="active">Still learning</option><option value="resolved">Mastered</option></select></label><button class="btn primary" data-action="practice-errors" ${entries.some(e=>e.m.status!=='resolved')?'':'disabled'}>PRACTICE ERRORS ${icon('target')}</button></div><div class="error-list">${entries.map(({m,l,q})=>`<article class="card error-card" data-error-status="${m.status==='resolved'?'resolved':'active'}"><div class="card-heading"><span class="tag ${m.status==='resolved'?'green':'orange'}">${m.status==='resolved'?'MASTERED':m.status==='learning'?'CORRECTED · KEEP PRACTICING':'NEEDS REVIEW'}</span><small>${m.wrongAttempts||1} wrong attempt(s)</small></div><small class="muted">${h(l.title)} · Lecture ${String(l.lecture).padStart(3,'0')}</small><h3>${h(q.prompt)}</h3><div class="error-answer"><span>Your last wrong answer</span><b>${h(m.lastAnswer||'Saved before answer history was added')}</b></div><div class="correct-answer"><span>Correct answer</span><b>${h(correctAnswer(q))}</b><p>${h(q.explanation)}</p></div><div class="error-footer"><small>${m.correctStreak||0}/2 clean recalls${m.lastMissedAt?' · '+new Date(m.lastMissedAt).toLocaleDateString():''}</small><button class="btn secondary" data-retry-key="${h(m.key)}">TRY AGAIN ${icon('arrow')}</button></div></article>`).join('')||`<div class="empty-state">${mascot()}<h2>A fresh start.</h2><p>Miss a puzzle and its explanation will appear here. Your mistakes become your personal practice plan.</p><button class="btn primary" data-action="practice">START A PRACTICE ROUND</button></div>`}</div>`;}
