async function loadCourse(id){
 if(loadedCourses.has(id))return loadedCourses.get(id);
 const response=await fetch('/api/course-content?subject='+encodeURIComponent(id),{signal:AbortSignal.timeout(15000)});
 if(response.status===401){lockAccount();throw Error('Please log in again.');}
 if(!response.ok)throw Error('Course content unavailable');
 const content=await response.json();
 if(content.subjectId!==id||!Array.isArray(content.units)||!content.units.length||!Array.isArray(content.lecturePlans)||!Array.isArray(content.lessons)||!content.lessons.length)throw Error('Invalid course content');
 loadedCourses.set(id,content);return content;
}
async function switchSubject(id,initial=false){
 if(!authenticated()){render();return;}
 const subject=subjects.find(s=>s.id===id&&s.status==='available')||subjects.find(s=>s.status==='available'),epoch=++subjectEpoch;
 session=null;closeDialog();loadingSubject=subject;subjectLoadError=null;
 if(!initial){route='learn';location.hash='learn';}render();
 try{
  const content=await loadCourse(subject.id);if(epoch!==subjectEpoch||!authenticated())return;
  selectedSubject=subject;units=content.units;lecturePlans=content.lecturePlans;lessons=content.lessons;storageKey=subject.storageKey;
  try{progress=experience(JSON.parse(store.getItem(storageKey)));}catch{progress=emptyProgress();}
  activeUnit=nextUnit(lessons,progress,units);status=null;loadingSubject=null;store.setItem('csquest-subject',subject.id);render();void pollStatus();
 }catch(error){if(epoch!==subjectEpoch)return;subjectLoadError=error.message;render();}
}
function subjectsView(){return `<div class="page-eyebrow">YOUR COMPUTER SCIENCE ADVENTURE</div><h1>One platform.<br>A world of CS.</h1><p class="page-description">Choose a subject. Your lessons, XP, mistakes, and milestones stay separate for each subject.</p><div class="catalog-tools"><label class="catalog-search"><span class="sr-only">Find a subject</span><input id="subject-search" type="search" placeholder="Find a subject…" value="${h(subjectQuery)}" autocomplete="off"></label><div class="catalog-filters" role="group" aria-label="Subject availability">${[['all','All subjects'],['available','Ready to learn'],['planned','Coming soon']].map(([id,label])=>`<button class="catalog-filter ${subjectFilter===id?'selected':''}" data-catalog-filter="${id}" aria-pressed="${subjectFilter===id}">${label}</button>`).join('')}</div></div><p class="catalog-count" role="status" id="catalog-count">${subjects.filter(s=>s.status==='available').length} ready to learn · ${subjects.filter(s=>s.status==='planned').length} coming soon</p><div class="subject-grid">${[...subjects].sort((a,b)=>Number(b.status==='available')-Number(a.status==='available')).map(subject=>{let saved;try{saved=normalizeProgress(JSON.parse(store.getItem(subject.storageKey)));}catch{saved=emptyProgress();}const planned=subject.status!=='available';return `<article class="card subject-card ${subject.color}" data-catalog-subject="${subject.id}" data-catalog-name="${h((subject.name+' '+subject.shortName).toLowerCase())}" data-catalog-status="${subject.status}"><div class="subject-icon">${icon(subject.icon)}</div><span class="tag ${subject.color}">${planned?'COMING SOON':subject.id===selectedSubject.id?'CURRENT SUBJECT':h(subject.shortName.toUpperCase())}</span><h2>${h(subject.name)}</h2><p>${h(subject.description)}</p><div class="subject-meta"><span>${subject.publishedLectureCount??subject.lectureCount} chapters</span><span>${planned?'Lessons in preparation':(subject.publishedLectureCount??subject.lectureCount)*3+' levels'}</span></div><small>${planned?'New lessons are on the way':courseCompletion(saved,(subject.publishedLectureCount??subject.lectureCount)*3).percent+'% complete · '+courseCompletion(saved,(subject.publishedLectureCount??subject.lectureCount)*3).completed+' levels · '+saved.xp+' XP'}</small>${subject.publishedLectureCount<subject.lectureCount?'<p class="tiny-note">More topics are being prepared.</p>':''}<button class="btn primary full" ${planned?'disabled aria-disabled="true"':`data-subject="${subject.id}"`}>${planned?'COMING SOON':saved.completed.length?'CONTINUE':'EXPLORE'} ${icon('arrow')}</button></article>`;}).join('')}</div><p class="no-subjects" id="no-subjects" hidden>No matching subjects. Try a shorter name or show all subjects.</p>`;}

function truthExercise(q){const s=session,disabled=s.feedback!==null?'disabled':'';return `<p class="exercise-hint">Choose the output for every input row. The complete table is your circuit’s rule.</p><div class="truth-table" style="--truth-inputs:${q.labels.length}"><div class="truth-row truth-heading">${q.labels.map(label=>`<b>${h(label)}</b>`).join('')}<b>OUTPUT</b></div>${q.rows.map((row,i)=>`<div class="truth-row">${row.map(v=>`<span class="input-bit">${v}</span>`).join('')}<div class="truth-output">${[0,1].map(bit=>`<button class="tile ${s.value[i]===bit?'chosen':''}" data-truth-row="${i}" data-truth-value="${bit}" ${disabled}>${bit}</button>`).join('')}</div></div>`).join('')}</div>`;}
function kmapExercise(q){const gray=[0,1,3,2],s=session,disabled=s.feedback!==null?'disabled':'';return `<p class="exercise-hint">Tap cells to form your group. Tap again to deselect. AB labels rows; CD labels columns.</p><div class="kmap-board"><span>AB / CD</span>${gray.map(g=>`<b>${g.toString(2).padStart(2,'0')}</b>`).join('')}${gray.map(r=>`<b>${r.toString(2).padStart(2,'0')}</b>${gray.map(col=>{const cell=r*4+col;return `<button class="kmap-cell ${s.value.includes(cell)?'selected':''} ${q.ones.includes(cell)?'one':''}" data-kmap-cell="${cell}" aria-label="Cell ${cell}, value ${q.ones.includes(cell)?1:0}" aria-pressed="${s.value.includes(cell)}" ${disabled}><small>m${cell}</small><strong>${q.ones.includes(cell)?1:0}</strong></button>`;}).join('')}`).join('')}</div><p class="muted">${s.value.length} cells selected · Groups must have power-of-two sizes.</p>`;}


function exampleTable(table){return table?`<div class="example-table-wrap"><table class="example-table"><thead><tr>${table.headers.map(v=>`<th scope="col">${h(v)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(v=>`<td>${h(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
function workedExampleCard(s){const example=createWorkedExample(s.lesson,s.queue[0].q);return `<div class="teaching-card worked-example" data-example-type="${h(example.type)}"><span class="tag blue">WORKED EXAMPLE</span><h3>${h(example.title)}</h3><p>${h(example.prompt)}</p>${cCode(s.queue[0].q)}${example.terms.length?`<div class="example-terms">${example.terms.map(v=>`<span>${h(v)}</span>`).join('')}</div>`:''}${example.facts.length?`<ul class="example-facts">${example.facts.map(v=>`<li>${h(v)}</li>`).join('')}</ul>`:''}${topicDiagram(s.lesson,selectedSubject.id,true)}${exampleTable(example.inputTable)}<button class="btn secondary" data-action="reveal-coach" aria-expanded="${Boolean(s.coachRevealed)}">${s.coachRevealed?'HIDE SOLUTION':'SHOW SOLUTION'} ${icon('arrow')}</button>${s.coachRevealed?`<div class="coach-answer">${example.answer?`<b class="example-result">${h(example.answer)}</b>`:''}${exampleTable(example.solutionTable)}${example.solutionList.length?`<ol class="example-steps">${example.solutionList.map(v=>`<li>${h(v)}</li>`).join('')}</ol>`:''}<p>${h(example.explanation)}</p></div>`:'<p class="muted">Study the given information, then reveal the solution and explanation. This example earns no XP.</p>'}</div>`;}

function refreshSubjects(){
 if(!authenticated())return Promise.resolve();
 if(catalogRefresh)return catalogRefresh;
 catalogRefresh=(async()=>{
  try{
   const response=await fetch('/api/subjects',{cache:'no-store',signal:AbortSignal.timeout(5000)});
   if(!response.ok)return;
   const latest=await response.json();
   if(!Array.isArray(latest)||JSON.stringify(latest)===JSON.stringify(subjects))return;
   subjects.splice(0,subjects.length,...latest);
   if(route==='subjects'&&!session)render();
  }catch{}finally{catalogRefresh=null;}
 })();
 return catalogRefresh;
}
function readStorage(key,fallback){try{const value=JSON.parse(store.getItem(key));return value??fallback;}catch{return fallback;}}
function savePreferences(){uiPrefs=preferences(uiPrefs);try{store.setItem('csquest-preferences',JSON.stringify(uiPrefs));}catch{toast('Your browser could not save settings.');}}
function uxContext(){const habit=habitSummary(subjects.filter(s=>s.status==='available').map(s=>s.id===selectedSubject.id?progress:readStorage(s.storageKey,null)));return {accountUser:account.user,progress:experience(progress),prefs:uiPrefs,habit,summary:practiceSummary(progress,lessons),latestDraft:readDrafts()[0],next:nextLesson(),subject:selectedSubject,allComplete:lessons.filter(l=>l.ready).every(l=>progress.completed.includes(l.id))};}
function readDrafts(){const raw=readStorage('csquest-drafts-'+selectedSubject.id,[]);if(!Array.isArray(raw))return [];return raw.map(d=>restoreRound(d,selectedSubject.id,lessons)).filter(d=>d&&(d.practice||available(d.lesson.id,lessons,progress))).sort((a,b)=>b.savedAt-a.savedAt);}
function persistSession(){if(!session||session.finished)return;try{const raw=readStorage('csquest-drafts-'+selectedSubject.id,[]),draft=serializeRound(session,selectedSubject.id);store.setItem('csquest-drafts-'+selectedSubject.id,JSON.stringify([...(Array.isArray(raw)?raw:[]).filter(d=>d.id!==draft.id),draft]));}catch{toast('Your browser could not save this paused round. Keep the tab open to finish.');}}
function removeDraft(id){const key='csquest-drafts-'+selectedSubject.id,raw=readStorage(key,[]);try{store.setItem(key,JSON.stringify((Array.isArray(raw)?raw:[]).filter(d=>d.id!==id)));}catch{}}
function resumeDraft(draft){session=draft;activeUnit=units.find(u=>draft.lesson.lecture>=u.range[0]&&draft.lesson.lecture<=u.range[1])?.id??activeUnit;openDialog('','lesson-dialog');renderSession();toast('Welcome back. Your answers are right here.');}
function continueLearning(){const draft=readDrafts()[0];if(draft){resumeDraft(draft);return;}const next=nextLesson();if(!next||progress.completed.includes(next.id)){startPractice();return;}startLesson(next.id);}
function focusKey(element){if(!element||element===document.body)return null;if(element.id)return '#'+CSS.escape(element.id);const attributes=[...element.attributes].filter(a=>a.name.startsWith('data-'));return attributes.length?attributes.map(a=>'['+a.name+'="'+CSS.escape(a.value)+'"]').join(''):null;}
function filterCatalog(){const cards=[...document.querySelectorAll('[data-catalog-subject]')];let visible=0;for(const card of cards){card.hidden=!card.dataset.catalogName.includes(subjectQuery.toLowerCase().trim())||(subjectFilter!=='all'&&card.dataset.catalogStatus!==subjectFilter);if(!card.hidden)visible++;}document.querySelectorAll('[data-catalog-filter]').forEach(button=>{const selected=button.dataset.catalogFilter===subjectFilter;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});const empty=document.querySelector('#no-subjects');if(empty)empty.hidden=visible>0;const counter=document.querySelector('#catalog-count');if(counter)counter.textContent=subjectQuery||subjectFilter!=='all'?visible+' matching subject'+(visible===1?'':'s'):subjects.filter(s=>s.status==='available').length+' ready to learn · '+subjects.filter(s=>s.status==='planned').length+' coming soon';}

document.addEventListener('input',e=>{if(e.target.id==='subject-search'){subjectQuery=e.target.value;filterCatalog();}});
window.addEventListener('pagehide',persistSession);
window.addEventListener('online',pollStatus);
setInterval(refreshSubjects,60000);
document.addEventListener('keydown',e=>{if(!session||session.finished||session.intro||e.isComposing||e.repeat||e.defaultPrevented)return;if(e.key==='Enter'&&e.ctrlKey&&!e.altKey&&!e.metaKey){const button=document.querySelector('[data-action="'+(session.feedback===null?'check-answer':'next-question')+'"]');if(button&&!button.disabled){e.preventDefault();button.click();}return;}if(e.altKey||e.ctrlKey||e.metaKey)return;const editable=e.target.matches('input,textarea,[contenteditable=true]');if(!editable&&session.feedback===null&&session.queue[session.index].q.type==='choice'&&/^[1-9]$/.test(e.key)){const button=document.querySelector('[data-choice="'+(Number(e.key)-1)+'"]');if(button){e.preventDefault();button.click();}}else if(e.key==='Enter'&&!e.defaultPrevented&&(!e.target.closest('button,a')||e.target.matches('[data-choice],[data-action="check-answer"],[data-action="next-question"]'))&&!e.target.matches('a,[data-action="concept-hint"],[data-source-info],[data-action="exit"],[data-action="resume"],[data-action="leave"],[data-action="theme"]')){const button=document.querySelector('[data-action="'+(session.feedback===null?'check-answer':'next-question')+'"]');if(button&&!button.disabled){e.preventDefault();button.click();}}});

async function reloadUser(){session=null;closeDialog();uiPrefs=preferences(readStorage('csquest-preferences',{}));await switchSubject(store.getItem('csquest-subject')||'coa',true);render();}
bindAccounts({render,reloadUser,toast,openDialog,closeDialog});
bindSocial({toast});
window.addEventListener('account-status',()=>{if(!authenticated()){render();return;}document.querySelectorAll('.account-sync').forEach(el=>el.textContent=syncText());});
window.addEventListener('focus',checkSession);
let studyTick=Date.now();setInterval(()=>{const now=Date.now(),elapsed=Math.min(2,(now-studyTick)/1000);studyTick=now;if(session&&!session.finished&&document.visibilityState==='visible'&&document.hasFocus()&&document.querySelector('.lesson-shell')){session.studySeconds=(session.studySeconds||0)+elapsed;if(Math.floor(session.studySeconds)%15===0)persistSession();}},1000);

document.addEventListener('aptitude-interaction',()=>sound('tap'));
document.addEventListener('algo-interaction',()=>sound('tap'));
document.addEventListener('c-interaction',()=>sound('tap'));
document.addEventListener('c-program-answer',event=>{
 if(!session||session.intro||session.feedback!==null)return;
 const q=session.queue[session.index].q,{index,token}=event.detail;
 if(q.type!=='c-program'||!Number.isInteger(index)||index<0||index>=q.answer.length||(token!==null&&!q.tokens.includes(token)))return;
 session.value[index]=token;renderSession();sound('tap');
 const next=session.value.findIndex(value=>value===null);
 document.querySelector(`[data-program-slot="${next<0?index:next}"]`)?.focus({preventScroll:true});
});

document.addEventListener('aptitude-puzzle-answer',event=>{if(!session||session.feedback!==null)return;session.value=event.detail;const check=document.querySelector('[data-action=check-answer]');if(check)check.disabled=!canCheck(session.queue[session.index].q,session.value);persistSession();});
